export const jsonToCsv = (data) => {
  const allKeys = new Set() // To collect all unique keys across all objects

  // 1. Collect all unique keys
  data.forEach((obj) => {
    Object.keys(obj).forEach((key) => allKeys.add(key))
  })

  const sortedKeys = Array.from(allKeys).sort() // Sort keys alphabetically for consistent order

  // 2. Prepare the header row (Key, Value1, Value2, ...)
  const header = ['Key', ...data.map((_, index) => `Value ${index + 1}`)]
  const csvRows = [header.join(',')]

  // 3. Create rows for each key
  sortedKeys.forEach((key) => {
    const row = [key] // Start the row with the key

    data.forEach((obj) => {
      row.push(obj[key] !== undefined ? obj[key] : '') // Add the value or an empty string
    })
    csvRows.push(row.join(','))
  })

  return csvRows.join('\n')
}

export const downloadCsv = (filename, data) => {
  const csvData = jsonToCsv([data])
  const blob = new Blob([csvData], { type: 'text/csv;charset=utf-8;' })
  const link = document.createElement('a')
  link.href = URL.createObjectURL(blob)
  link.setAttribute('download', filename)
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
}
