import React, { useState } from 'react'
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
} from '@material-ui/core'
import { GetApp } from '@material-ui/icons'

import ActionButton from '../ActionButton'
import { downloadCsv } from '../../utils'

const ExportTeacherDataAlert = ({ data, teacher }) => {
  const [open, setOpen] = useState(false)

  const handleClickOpen = () => {
    setOpen(true)
  }

  const handleClose = () => {
    setOpen(false)
  }

  const handleSubmit = () => {
    setOpen(false)
    downloadCsv(
      `Chem Cash Data - ${teacher.firstName} ${teacher.lastName}.csv`,
      data
    )
  }

  return (
    <>
      <ActionButton action='Export teacher data' onClick={handleClickOpen}>
        <GetApp />
      </ActionButton>
      <Dialog
        open={open}
        onClick={(ev) => ev.stopPropagation()}
        onClose={handleClose}
        onFocus={(ev) => ev.stopPropagation()}
      >
        <DialogTitle>Export Teacher Data</DialogTitle>
        <DialogContent>
          <DialogContentText component='div'>
            Are you sure you want to export data for{' '}
            <b>
              {teacher.firstName} {teacher.lastName}
            </b>
            ?
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={handleSubmit}
            color='secondary'
            variant='contained'
            autoFocus
          >
            Download
          </Button>
          <Button onClick={handleClose} variant='contained'>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  )
}

export default ExportTeacherDataAlert
